using System.Text;public class Solution{public string RemoveDuplicateLetters(string s){int[]last=new int[26];bool[]used=new bool[26];for(int i=0;i<s.Length;i++)last[s[i]-'a']=i;var r=new StringBuilder();for(int i=0;i<s.Length;i++){char c=s[i];int k=c-'a';if(used[k])continue;while(r.Length>0&&r[^1]>c&&last[r[^1]-'a']>i){used[r[^1]-'a']=false;r.Length--;}r.Append(c);used[k]=true;}return r.ToString();}}
